/** The font at ROOT as 96 glyphs of 8 rows, 20h to 7Fh. */
export function fontGlyphs(root) {
  const text = readFileSync(resolve(root, "format/font5x7.txt"), "utf8");
  const glyphs = new Map();
  let rows;
  for (const line of text.split(/\r?\n/)) {
    if (line.trim() === "" || (line.startsWith("#") && !/^[#.]{5}$/.test(line))) continue;
    const head = /^= ([0-9A-F]{2})$/.exec(line);
    if (head) {
      const code = parseInt(head[1], 16);
      if (code < 0x20 || code > 0x7f || glyphs.has(code)) throw new Error(`font: duplicate or out-of-range glyph ${head[1]}`);
      rows = [];
      glyphs.set(parseInt(head[1], 16), rows);
      continue;
    }
    if (!/^[#.]{5}$/.test(line)) throw new Error(`font: bad row ${JSON.stringify(line)}`);
    if (!rows || rows.length >= 8) throw new Error("font: row outside an eight-row glyph");
    rows.push(parseInt(line.replace(/#/g, "1").replace(/\./g, "0"), 2) << 3);
  }
  const out = [];
  for (let c = 0x20; c < 0x80; c += 1) {
    const g = glyphs.get(c);
    if (!g || g.length !== 8) throw new Error(`font: glyph ${c.toString(16)} missing or not 8 rows`);
    out.push(g);
  }
  return out;
}

/** The font as 768 bytes. */
export const fontBytes = (root) => Uint8Array.from(fontGlyphs(root).flat());

/** The font as source: a heading, the label FONT and DB rows. */
export function fontSource(root, heading) {
  const rows = fontGlyphs(root).map((g) => `\tDB\t${g.map(hex).join(",")}`);
  return [heading, "FONT:", ...rows].join("\n") + "\n";

export function fontPackage(root) {
  const font=Buffer.from(fontBytes(root));
  assert.equal(sha(font),'5d732cefca4013fe6082728a00cae5e3aceaf3e6eb99aaa31e0289c0b3efe1d8','selected font identity');
  const original=readFileSync(resolve(root,'format/font-original.bin'));
  assert.equal(sha(original),'43eb0ec9a8513a670df112948435801b9ae91874e1d17f1283d8990e586e0fb0','original font identity');
  assert.equal(sha(readFileSync(resolve(root,'format/font5x7-original.txt'))),'ba4aaea026956d45e384de39e622a02d5b672e3df17f74714732bb05a27c3c3e','original source identity');
  const notices=readFileSync(resolve(root,'format/FONT-NOTICES.txt'));
  validateFontNotices(notices);
  return {font,original,notices};
}
/** Exact full copyright, conditions, disclaimer, origin limits and edits. */
export function validateFontNotices(notices) {
  assert.equal(sha(notices),'577c3e97edcf1d7e183f4b668ec93a3125c90a414a6203fb3194ba6a6c612b41','complete selected font notices');
}

